R,C=23,28
out=[[1]*C for _ in range(R)]
zeros={2:[3,5,7,9],4:list(range(4,25,2)),5:[3,5],6:[17,19,21,23,25],7:[4,6,8,10,12,14],9:[2,4,6],10:[8,10,12,14,16],11:[3,5,7,9,11],12:[5,7,9,11,13,15,17],14:[6,8,10,12,14],15:[10,12,14,16,18,20],17:[0,2,4,6,8,10,12],18:[2,4],19:[1,3],20:[6,8,10,12,14,16,18],21:[11,13,15,17,19,21,23],22:[2,4]}
for r,cs in zeros.items():
 for c in cs: out[r][c]=0
for r,cs in zeros.items():
 for c in cs:
  if c>0 and c+1<C and out[r][c-1]==0 and out[r][c+1]==0:
   out[r][c]=2
# But loop overwrites original zero if own adjacent zeros; reset marker positions to 0
for r,cs in zeros.items():
 for c in cs: out[r][c]=0
# then fill strict intervening positions only
for r,cs in zeros.items():
 for c in range(C):
  if out[r][c]==1 and c>0 and c+1<C and out[r][c-1]==0 and out[r][c+1]==0:
   out[r][c]=2
assert len(out)==23 and all(len(x)==28 for x in out)
print('\n'.join(' '.join(map(str,x)) for x in out))

